-- Forever (Classic 1.60): русские приветствия NPC в окне заданий. Готовый перевод из базы Classic (по номеру существа и тексту)
-- и ручной перевод остальных. Меняет только пустые значения. Можно запускать повторно.

ON DUPLICATE KEY UPDATE `Greeting` = IF(`Greeting` IS NULL OR `Greeting` = '', VALUES(`Greeting`), `Greeting`);
