INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES
(464, 0, 'ruRU', 'Не упускай из виду цель, $r.', 0),
(2215, 0, 'ruRU', 'Чтобы служить Темной Госпоже и Вариматразу, мы должны продвинуть фронт против людской заразы.', 0),
(2988, 0, 'ruRU', 'Долг Гонцов – обеспечивать безопасность тех, кто путешествует по равнинам Мулгора. Те, кто угрожает безопасности родины тауренов, рискуют понести наказание от наших рук.', 0),
(4088, 0, 'ruRU', 'Путь воина – это путь решимости, $gбрат:сестра;.  Он может начаться с силы оружия, но держится на силе воли.', 0),
(5770, 0, 'ruRU', 'Если мы хотим защитить природу, мы должны принять ее силу.  И должны показать эту силу тем, кто хочет навредить земле.', 0),
(6142, 0, 'ruRU', 'Мастерство ночных эльфов простирается дальше лесов и их обитателей.  Мы многое знаем о недрах земли и о металлах в них.', 0),
(7623, 0, 'ruRU', 'Использование Каменора как базы для операций в болотах дает нам явное преимущество в разведывательных и наступательных вылазках.', 0),
(9078, 0, 'ruRU', 'Дорогой $gмальчик:девочка;, ты $Gпришелел:пришелла; как раз вовремя, чтобы помочь экспедиционному отряду Каргата.', 0)
